<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="page-title mb-1"><?=$title?></h1><p class="subtle mb-0"><?=!empty($is_import)?'Unggah PO BP untuk membaca nomor dan tanggal otomatis. Tetap periksa hasil sebelum simpan.':'Pilih detail Service Order yang telah disetujui.'?></p></div><a class="btn btn-light" href="<?=site_url('purchase-orders')?>"><i class="bi bi-arrow-left me-1"></i>Kembali</a></div>
<div class="card"><div class="card-body p-4"><?=form_open_multipart()?><div class="row g-3"><?php if(!empty($is_import)):?><div class="col-12"><div class="p-3 rounded-3" style="background:#edf7ff;border:1px dashed #71b7ed"><div class="d-flex align-items-center gap-3"><span class="stat-icon"><i class="bi bi-file-earmark-pdf"></i></span><div class="flex-grow-1"><div class="fw-semibold">Unggah Purchase Order dari BP</div><small class="subtle">Format PDF BP akan dibaca di browser untuk mengisi nomor PO dan tanggal. File asli disimpan ketika PO dibuat.</small></div><input class="form-control" style="max-width:320px" type="file" id="po_pdf" name="po_pdf" accept="application/pdf"></div></div></div><?php endif;?><div class="col-md-4"><label class="form-label fw-semibold">Nomor PO</label><input required class="form-control" id="po_number" name="po_number" value="<?=html_escape($po->po_number??'')?>" <?= $po?'readonly':''?>></div><div class="col-md-4"><label class="form-label fw-semibold">Tanggal PO</label><input required type="date" class="form-control" id="po_date" name="po_date" value="<?=$po->po_date??date('Y-m-d')?>"></div><div class="col-md-4"><label class="form-label fw-semibold">Vendor</label><input required class="form-control" name="vendor" value="<?=html_escape($po->vendor??'Surveyor Indonesia, PT')?>"></div></div><?php if(!$po):?><div class="d-flex align-items-center justify-content-between mt-4 mb-2"><h5 class="mb-0">Item dari SO Approved</h5><span class="small subtle">Masukkan qty sesuai PO BP</span></div><div class="table-wrap p-0"><div class="table-responsive"><table class="table"><thead><tr><th>SO</th><th>Part Number</th><th>Deskripsi</th><th>Sisa Qty</th><th>Harga</th><th style="width:140px">Qty PO</th><th>Keterangan</th></tr></thead><tbody><?php foreach($details as $d):?><tr data-match="<?=html_escape(strtolower($d->part_number))?>"><td><span class="small fw-semibold"><?=$d->so_number?></span></td><td class="fw-semibold"><?=$d->part_number?></td><td><?=$d->description?></td><td><?=$d->remaining?></td><td><?=rupiah($d->unit_price)?></td><td><input max="<?=$d->remaining?>" min="0" step="0.01" type="number" class="form-control po-qty" name="qty[<?=$d->so_detail_id?>]"></td><td><input class="form-control" name="notes[<?=$d->so_detail_id?>]"></td></tr><?php endforeach;?></tbody></table></div></div><?php else:?><select class="form-select mt-3" name="status"><option <?=$po->status==='Draft'?'selected':''?>>Draft</option><option <?=$po->status==='Completed'?'selected':''?>>Completed</option></select><?php endif;?><div class="d-flex gap-2 mt-4"><button class="btn btn-primary"><i class="bi bi-check2-circle me-1"></i>Simpan Purchase Order</button><a class="btn btn-light" href="<?=site_url('purchase-orders')?>">Batal</a></div><?=form_close()?></div></div>
<?php if(!empty($is_import)):?><script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js"></script><script>pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';document.getElementById('po_pdf').addEventListener('change',async function(e){const file=e.target.files[0];if(!file)return;try{const pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;let text='';for(let n=1;n<=pdf.numPages;n++){text+=(await (await pdf.getPage(n)).getTextContent()).items.map(i=>i.str).join(' ')+'\n'}const no=text.match(/Purchase Order No:\s*(\d+)/i)||text.match(/Purchase Order\s+(\d+)/i);if(no)document.getElementById('po_number').value=no[1];const dt=text.match(/Order Date:\s*(\d{2})-([A-Z]{3})-(\d{4})/i);if(dt){const months={JAN:0,FEB:1,MAR:2,APR:3,MAY:4,JUN:5,JUL:6,AUG:7,SEP:8,OCT:9,NOV:10,DEC:11};document.getElementById('po_date').value=`${dt[3]}-${String(months[dt[2].toUpperCase()]+1).padStart(2,'0')}-${dt[1]}`}document.querySelectorAll('tr[data-match]').forEach(row=>{const part=row.dataset.match;const exact=text.toLowerCase().includes(part);if(exact){row.style.background='#e9f8f1';row.querySelector('.po-qty').value='1'}});alert('Header PO berhasil dibaca. Baris hijau terdeteksi dari PDF; periksa dan sesuaikan qty sebelum menyimpan.')}catch(err){alert('PDF tidak dapat dibaca otomatis. Isi header dan item secara manual.')}});</script><?php endif;?>
